extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var player := find_by_name(main, "Player") as CharacterBody2D
	var guard := find_by_name(main, "Guard") as CharacterBody2D
	var coin := find_by_name(main, "Coin") as Area2D
	if not check("player", player != null, "Nella scena deve esserci il Player"):
		return
	if not check("coin", coin != null, "Nella scena principale deve esserci un'istanza dell'oggetto chiamata Coin"):
		return

	var initial_coins = get_prop(player, "coins", -1)
	if not check("has_coins", typeof(initial_coins) == TYPE_INT and initial_coins == 0, "Player deve avere una variabile intera 'coins' inizializzata a 0"):
		return

	# Muoviamo la guardia sopra la moneta
	if guard != null:
		guard.global_position = coin.global_position
		await wait_physics_frames(5)
		var coins_after_guard = get_prop(player, "coins", 0)
		check("guard_no_collect", coins_after_guard == 0, "Una guardia non deve poter raccogliere gli oggetti")
		check("coin_still_alive", is_instance_valid(coin) and not coin.is_queued_for_deletion(), "L'oggetto Coin non deve sparire se toccato da una guardia")
		guard.global_position = Vector2(-500.0, -500.0)
		await wait_physics_frames(2)

	# Muoviamo il giocatore sopra la moneta
	player.global_position = coin.global_position
	await wait_physics_frames(5)
	var coins_after_player = get_prop(player, "coins", 0)
	check("player_collects", coins_after_player == 1, "Raccogliendo la moneta, player.coins deve aumentare di 1 (trovato: %s)" % str(coins_after_player))
	check("coin_freed", not is_instance_valid(coin) or coin.is_queued_for_deletion(), "Dopo la raccolta, l'oggetto Coin deve essere rimosso dalla scena con queue_free()")

